import{z as B,x as A,o,c as i,q as c,j as l,D as r,d as e,s,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Reactor / Proactor","description":"","frontmatter":{"title":"Reactor / Proactor","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reactor-proactor.md","filePath":"cs/reactor-proactor.md","lastUpdated":1791413859000}'),p={name:"cs/reactor-proactor.md"};function d(P,a,h,C,m,u){const E=A("Mermaid");return o(),i("div",null,[a[2]||(a[2]=c('<h1 id="reactor-proactor" tabindex="-1">Reactor / Proactor <a class="header-anchor" href="#reactor-proactor" aria-label="Permalink to &quot;Reactor / Proactor&quot;">​</a></h1><div class="epigraph"><p>Reactor 等就绪再同步读写；Proactor 把异步完成当事件。两者把「一线程一连接」换成事件循环，才能接近线速套接字。</p><footer>—— 据 Schmidt, Reactor, POSA2；Proactor 模式对照；Stevens UNP 整理</footer></div><p>主干<a href="/cs/socket-nonblock">非阻塞套接字</a> 已给 O_NONBLOCK。<a href="/cs/network-simulation">上一课</a> 不写主机程序。缺口是<strong>事件分派模式</strong>：select/epoll vs IOCP/io_uring。本课不把 C10K 数字写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>阻塞 <code>recv</code> 一连接一线程，万连接炸栈。<a href="/cs/socket-nonblock">非阻塞</a> 要自己问谁就绪。Reactor：多路复用（epoll）→ 分派 handler → 非阻塞 I/O。Proactor：提交异步读，完成队列回调，数据已在缓冲。Linux 历史偏 Reactor，io_uring 靠向 Proactor。TSO/GRO 减事件次数。</p><p><span class="marginnote">直觉类比：Reactor 像餐厅广播「3 号桌的菜好了」，你自己去窗口端菜（就绪通知 + 亲自读）；Proactor 像服务员直接把菜端到你桌上再喊你（完成通知，数据已放进你的缓冲区）。差别全在「谁来干活」：前者内核只报告状态，后者内核把 I/O 做完。</span></p><p><span class="marginnote">数字实例：一连接一线程时，1 万个连接就是 1 万个线程。每个线程默认 1–8 MB 栈，光栈就吃掉 10–80 GB，上下文切换的调度开销也随之爆炸。事件循环用几个线程就能扛同样的连接数——这正是 C10K 问题的解法起点。</span></p><p>不要把模式写成语言框架名。</p><p><span class="marginnote">POSA2 Reactor。本课不把每套 API 参数背完。</span></p><h3 id="i-o-线程必须短" tabindex="-1">I/O 线程必须短 <a class="header-anchor" href="#i-o-线程必须短" aria-label="Permalink to &quot;I/O 线程必须短&quot;">​</a></h3><p>就绪再读 vs 完成再回调。循环里阻塞 DNS 会冻整服务。重 CPU 应下到线程池。不是语言框架名。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照两种时序图。画：等待 → 就绪/完成 → 处理。与交换机：都是事件驱动，一层主机，一层 ASIC。</p>',13)),(o(),l(n,null,{default:r(()=>[s(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20RX%5B%22Reactor%3A%20%E5%B0%B1%E7%BB%AA%E5%88%99%E8%AF%BB%22%5D%20--%3E%20H%5B%22handler%22%5D%0A%20%20PX%5B%22Proactor%3A%20%E5%AE%8C%E6%88%90%E5%88%99%E5%9B%9E%E8%B0%83%22%5D%20--%3E%20H%0A%20%20MX%5B%22epoll%2FIOCP%22%5D%20--%3E%20RX%0A%20%20MX%20--%3E%20PX%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"反向代理、QUIC 用户态栈都是这种循环。SSH 按键也是。线程池可放在 handler 后做业务，I/O 线程不阻塞——否则 Reactor 假死。与 PTP 无关。",-1)),(o(),l(n,null,{default:r(()=>[s(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%BA%94%E7%94%A8%E8%A6%81%E8%AF%BB%E4%B8%80%E6%AC%A1%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20Q%7B%22%E9%80%89%E5%93%AA%E7%A7%8D%E6%A8%A1%E5%BC%8F%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22Reactor%22%7C%20R1%5B%22epoll%20%E6%8A%A5%E5%91%8A%EF%BC%9Asocket%20%E5%8F%AF%E8%AF%BB%E4%BA%86%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E5%BA%94%E7%94%A8%E8%87%AA%E5%B7%B1%E8%B0%83%20recv%20%E6%8A%8A%E5%AD%97%E8%8A%82%E6%8B%B7%E8%BF%9B%E6%9D%A5%22%5D%0A%20%20R2%20--%3E%20R3%5B%22%E6%8B%BF%E5%88%B0%E6%95%B0%E6%8D%AE%EF%BC%8C%E5%BC%80%E5%A7%8B%E5%A4%84%E7%90%86%22%5D%0A%20%20Q%20--%3E%7C%22Proactor%22%7C%20P1%5B%22%E5%85%88%E5%90%91%E5%86%85%E6%A0%B8%E6%8F%90%E4%BA%A4%E4%B8%80%E6%AC%A1%E5%BC%82%E6%AD%A5%E8%AF%BB%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E5%86%85%E6%A0%B8%E5%AE%8C%E6%88%90%E8%AF%BB%E5%8F%96%E5%B9%B6%E5%A1%AB%E5%A5%BD%E7%94%A8%E6%88%B7%E7%BC%93%E5%86%B2%E5%8C%BA%22%5D%0A%20%20P2%20--%3E%20P3%5B%22%E5%AE%8C%E6%88%90%E4%BA%8B%E4%BB%B6%E5%9B%9E%E8%B0%83%EF%BC%8C%E6%95%B0%E6%8D%AE%E5%B7%B2%E5%9C%A8%E6%89%8B%E4%B8%8A%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=c('<p><span class="marginnote">常见误区：初学者容易在事件循环的 handler 里顺手调一个阻塞的 DNS 解析或同步数据库查询。这一阻塞不是只慢这一路——整个循环的其余上万连接都在同一条线程上排队，表现为「服务整体假死」。重活必须丢给线程池，I/O 线程只做拷贝与分派。</span></p><p>安全：事件循环里不要做重 CPU，否则延迟像膨胀。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每种开源库。C10K 与并发模型是下一课。后课默认：高并发 I/O 用 Reactor 或 Proactor，不是一连接一线程。</p><p>在循环里再阻塞 DNS 查询会把整个服务卡住。</p><p>下一课<a href="/cs/c10k-concurrency">C10K 与并发模型</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Reactor 等就绪；Proactor 等完成。</li><li>多路复用是共同前提。</li><li>I/O 线程必须短而非阻塞。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Schmidt Reactor；UNP。</li></ul>',8))])}const f=B(p,[["render",d]]);export{_ as __pageData,f as default};
